 {Bytes ram=base_ram("");put(ram,NODE+0x5e,1,6);put(ram,NODE+0x5f,1,0x5a);put(ram,NODE+0x8a,2,0x77);State s=pre(0xcc8c0,0x12345678,0);
  check(runs_to(ram,s,0x49f8c)&&get(ram,NODE+0x5e,2)==0U&&s.d[0]==0x12340100U&&s.a[1]==0xce758U&&get(ram,NODE+0x20,2)==0x77U,"cc8c0 6 -> cc8d2 -> cc8f6 -> ccbc0 8c 0");}
 {Bytes ram=base_ram("");put(ram,NODE+0x5e,1,0x1b);put(ram,NODE+0x8c,2,1);State s=pre(0xcc8c0,0x12345678,0);check(runs_to(ram,s,0x49f8c)&&s.a[1]==0xce7c4U&&
  get(ram,NODE+0x5e,1)==0U,"cc8c0 1b -> ccbc0 (unsigned BYTE >= 1b)");}
 {Bytes ram=base_ram("");put(ram,NODE+0x5e,1,0xff);put(ram,NODE+0x8c,2,2);State s=st(0xcc8c0);check(runs_to(ram,s,0x49f8c)&&s.a[1]==0xd0060U,"cc8c0 ff -> ccbc0");}
 {Bytes ram=base_ram("");put(ram,NODE+0x5e,1,0x1a);State s=st(0xcc8c0);check(runs_to(ram,s,0xcc946)&&(s.d[0]&0xffffU)==0x68U,"cc8c0 1a -> cc946 (entry 26)");}
 {Bytes ram=base_ram("");State s=pre(0xcc8d2,0x12340106,0);check(runs_to(ram,s,0x49f8c)&&s.d[0]==0x12340100U,"cc8d2 106 -> entry 6");}
 {Bytes ram=base_ram("");State s=pre(0xcc8d2,0xffff0101,0);check(runs_to(ram,s,0xcc8e2)&&s.d[0]==0xffff0004U,"cc8d2 0101 -> entry 1 (cc8e2)");}
 // every table entry k is reached by the index k (TABLE: cc8de + 4k; only cc8f6 is an FR13 block, the others stop as unrouted PCs).
 {const unsigned int n=sizeof(TABLE)/sizeof(TABLE[0]);check(n==27U&&TABLE[0]==0xcc8deU&&TABLE[26]==0xcc946U,"table cc8de");
  for(unsigned int k=0;k<n;++k){check(in_ranges(TABLE[k])==(TABLE[k]==0xcc8f6U),"table entry routed only at cc8f6",TABLE[k]);
   Bytes ram=base_ram("");State s=pre(0xcc8d2,0x5a5a5a00U|k,0);check(runs_to(ram,s,TABLE[k])&&s.d[0]==(0x5a5a0000U|(4U*k)),"cc8d2 index k",k);}}
 {Bytes ram=base_ram("");State s=pre(0xcc8d2,0x1234011b,0);reject(ram,s,STOP,JUMP_ERROR);}
 {Bytes ram=base_ram("");State s=pre(0xcc8d2,0x80,0);reject(ram,s,STOP,JUMP_ERROR);}
 {Bytes ram=base_ram("");State s=pre(0xcc8d2,0x1c,0);reject(ram,s,STOP,JUMP_ERROR);}
 // ccbc0: WORD 8c 0..4 select ce758 ce7c4 d0060 cf126 d00e0, other d07f8; ccc80: (A6) := cdd2e; RTS.
 {const std::uint32_t anim[]={0xce758,0xce7c4,0xd0060,0xcf126,0xd00e0,0xd07f8,0xd07f8,0xd07f8,0xd07f8,0xd07f8,0xd07f8,0xd07f8};
  const std::uint32_t sel[]={0,1,2,3,4,5,0x100,0xffff,0x101,0x102,0x103,0x104};   // CMPI.W: the WORD 8c (0x101 .. 0x104 differ from 1 .. 4 in the high BYTE)
  for(unsigned int i=0;i<12;++i){Bytes ram=base_ram("");put(ram,NODE+0x8c,2,sel[i]);put(ram,NODE+0x8a,2,0x1234);State s=pre(0xccbc0,0xabcd0000,0);
   check(runs_to(ram,s,0x49f8c)&&s.a[1]==anim[i]&&s.d[0]==0xabcd0100U&&get(ram,NODE+0x20,2)==0x1234U,"ccbc0 anim select",sel[i]);}}
 {Bytes ram=base_ram("");State s=st(0xccbde);check(runs_to(ram,s,STOP)&&get(ram,NODE,4)==0xcdd2eU,"ccbde -> ccc80 writes cdd2e");}
 // cca5a: MOVEQ #0,D0; MOVE.W (A0),D0; SWAP; BTST #0,15; BNE / NEG.L; LONG 36 / 64 := D0; RTS.
 {Bytes ram=base_ram("");put(ram,REC,2,0x8000);State s=pre(0xcca5a,0x12345678,0);s.a[0]=REC;check(runs_to(ram,s,STOP)&&s.d[0]==0x80000000U&&
  get(ram,NODE+0x36,4)==0x80000000U&&get(ram,NODE+0x64,4)==0x80000000U,"cca5a 8000 NEG.L");}
 {Bytes ram=base_ram("");put(ram,REC,2,0x0001);State s=pre(0xcca5a,0x12345678,0);s.a[0]=REC;check(runs_to(ram,s,STOP)&&s.d[0]==0xffff0000U,"cca5a 1 -> ffff0000");}
 {Bytes ram=base_ram("");put(ram,REC,2,0x0001);put(ram,NODE+0x15,1,1);State s=pre(0xcca5a,0x12345678,0);s.a[0]=REC;check(runs_to(ram,s,STOP)&&s.d[0]==0x10000U&&
  get(ram,NODE+0x64,4)==0x10000U,"cca5a 1 bit 0 set -> 10000");}
