 {Bytes ram=base_ram("");State s=pre(0xd159e,0x12345678,0);check(runs_to(ram,s,0x2986)&&s.a[0]==0xd15c4U&&s.d[0]==0x12340014U&&s.a[1]==0x100bf4U,"d159e");}
