 // d161a: MOVEQ #18,D0; ADDI.W #18,32 (WORD); MOVE.L #18000,D1; BTST #0,15 -> d1636: ADD.W D0,2e; LONG 36 := D1; (A6) := d1644 -> d1654 ease.
 {Bytes ram=base_ram("");put(ram,NODE+0x15,1,1);put(ram,NODE+0x32,2,0xffe8);put(ram,NODE+0x2e,2,0xfff0);State s=pre(0xd161a,0x12345678,0);
  check(runs_to(ram,s,0x4be34)&&get(ram,NODE+0x32,2)==0U&&get(ram,NODE+0x30,2)==0U&&get(ram,NODE+0x2e,2)==8U&&get(ram,NODE+0x36,4)==0x18000U&&
  get(ram,NODE,4)==0xd1644U&&get(ram,NODE+0x3a,4)==0xffff8000U&&s.d[0]==0xffff8000U&&s.d[1]==0x18000U,"d161a -> d1636 -> d1644 -> d1654");}
 {Bytes ram=base_ram("");put(ram,NODE+0x15,1,0x80);State s=st(0xd1644);check(runs_to(ram,s,0x4be34)&&get(ram,NODE,4)==0xd16aeU,"d1644 bit 7 -> d164e writes d16ae");}
 {Bytes ram=base_ram("");put(ram,NODE+0x3a,4,0xfff0001f);State s=st(0xd1654);check(runs_to(ram,s,0x4be34)&&s.d[0]==0xffffffffU&&get(ram,NODE+0x3a,4)==0xfff0001eU,
  "d1654 ffffffe1 >> 5 = ffffffff");}
 {Bytes ram=base_ram("");put(ram,NODE+0x3a,4,0x80000000);State s=st(0xd1654);check(runs_to(ram,s,0x4be34)&&s.d[0]==0x03ff8000U&&get(ram,NODE+0x3a,4)==0x83ff8000U,
  "d1654 7ff00000 >> 5");}
 {Bytes ram=base_ram("");State s=st(0xd170e);check(runs_to(ram,s,0x4be34)&&get(ram,NODE+0x3a,4)==0xffffa000U&&get(ram,SP-4,4)==0xd1724U,"d170e fff40000 >> 5");}
 // d1670: MOVE.W -7ff2(A5) (10000e); ANDI.W #3; BNE d1698 / BYTE 14 vs 19 -> 14 := 19 / 1a; d1698: LEA d13a4; JSR 1ab80.
 {Bytes ram=base_ram("");put(ram,0x10000e,2,0xfff4);put(ram,NODE+0x14,1,5);put(ram,NODE+0x19,1,5);put(ram,NODE+0x1a,1,7);State s=pre(0xd1670,0x12345678,0);
  check(runs_to(ram,s,0x1ab80)&&s.d[0]==0x12340005U&&get(ram,NODE+0x14,1)==7U&&s.a[0]==0xd13a4U,"d1670 & 3 = 0; 14 = 19 -> 1a");}
 {Bytes ram=base_ram("");put(ram,NODE+0x14,1,5);put(ram,NODE+0x19,1,6);State s=st(0xd1670);check(runs_to(ram,s,0x1ab80)&&get(ram,NODE+0x14,1)==6U,"d1670 14 != 19 -> 19");}
 {Bytes ram=base_ram("");put(ram,0x10000e,2,0x0003);put(ram,NODE+0x14,1,5);State s=st(0xd1670);check(runs_to(ram,s,0x1ab80)&&(s.d[0]&0xffffU)==3U&&
  get(ram,NODE+0x14,1)==5U,"d1670 & 3 = 3 -> d1698");}
 // -7ff2(A5) is a negative displacement: with A5 = 1f8000 it addresses 1f000e (the work RAM mirror of 10000e), not 20000e.
 {Bytes ram=base_ram("");put(ram,0x10000e,2,0x0002);put(ram,NODE+0x14,1,5);State s=st(0xd1670);s.a[5]=0x1f8000;check(runs_to(ram,s,0x1ab80)&&(s.d[0]&0xffffU)==2U&&
  get(ram,NODE+0x14,1)==5U,"d1670 A5 1f8000: -7ff2(A5) = 1f000e (mirror)");}
 {Bytes ram=base_ram("");State s=carried(0xd16a2,2);check(runs_to(ram,s,0x2a00),"d16a2 Set -> JMP 2a00");}
 {Bytes ram=base_ram("");State s=carried(0xd16a2,1);check(runs_to(ram,s,STOP),"d16a2 Clear -> RTS");}
 // d16d6: LONG 36 / 3a / 64 := 0; WORD 76 := 78; (A6) := d16fa.  d172e: SUBQ.W #1,76; BCC (no borrow).
